template <class T>
struct DefaultProvider {
    static T value() { return T{}; }
};

template <class T>
T utility_func() { return DefaultProvider<T>::value(); }

template <class T>
void worker(T arg,
            T def_arg = utility_func<T>()) {
    // def_arg's default expression (utility_func<T>())
    // is dependent on T.

    // Instantiation Timing:
    // This default argument is compiled/instantiated
    // *per specialization* (e.g., worker<int>, worker<float>)
    // when the call omits the argument.
}
